pub fn rle(input: &str) -> String {
    let mut out = Vec::new();
    let mut count = 1;
    for (i, c) in input.chars().enumerate() {
        if i == 0 || c == input.chars().nth(i - 1).unwrap_or('?') {
            count += 1;
        } else {
            out.push_str(&format!("{}{}", count, char::from(c)));
            count = 1;
        }
    }
    out.push_str(&format!("{}{}", count, char::from(input.chars().nth(input.chars().count() - 1).unwrap_or('?'))));
    out
}

