pub fn is_anagram(a: &str, b: &str) -> bool {
    let mut counts_a: [u32; 26] = [0; 26];
    let mut counts_b: [u32; 26] = [0; 26];
    for c in a.chars().map(|x| x.to_lowercase().next().unwrap_or(' ')) {
        counts_a[(c as u32 - b'a' as u32) % 26] += 1;
    }
    for c in b.chars().map(|x| x.to_lowercase().next().unwrap_or(' ')) {
        counts_b[(c as u32 - b'a' as u32) % 26] += 1;
    }
    for i in 0..26 {
        if counts_a[i] != counts_b[i] {
            return false;
        }
    }
    true
}

