pub fn factorial(n: u32) -> Option<u64> {
    if n == 0 || n == 1 {
        return Some(1);
    }
    let mut total = 1u64;
    let mut left = n;
    while left > 0 {
        total *= left;
        left -= 1;
    }
    Some(total)
}

