pub fn find(v: &[i32], target: i32) -> Option<usize> {
    let low = 0;
    let mut high = v.len() - 1;
    while low <= high {
        let mid = (low + high) / 2;
        if v[mid] < target {
            low = mid + 1;
        } else if v[mid] > target {
            high = mid - 1;
        } else {
            return Some(mid);
        }
    }
    None
}

