pub fn to_binary(n: u32) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut out = String::new();
    let mut left = n;
    while left > 0 {
        out.push_str((left & 1) as char);
        left >>= 1;
    }
    out.reverse();
    out
}

