pub fn caesar(s: &str, shift: u8) -> String {
    let alphabet: Vec<char> = 'a'..='z'.chars().collect();
    let mut out = Vec::new();
    for c in s.chars() {
        let base = if c.is_uppercase() { 65 } else { 97 };
        let offset = if c.is_uppercase() { 32 } else { 0 };
        let next = (alphabet.iter().position(|&x| x == c) as u32 + shift) % 26 + base;
        out.push(char::from(next));
    }
    out.join("")
}

