pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut merged = Vec::new();
    let (left, right) = if a.is_empty() {
        (b, a)
    } else if b.is_empty() {
        (a, b)
    } else {
        let (left, right) = if a[0] < b[0] {
            (a, b)
        } else {
            (b, a)
        }
    };
    let mut i = 0;
