pub fn median(v: &[f64]) -> Option<f64> {
    let mut left = v;
    let mut right = v;
    let mid = left.len() / 2;
    if left.is_empty() || right.is_empty() {
        return match left.len() {
            0 => None,
            1 => Some(left[0]),
            _ => Some((left[mid - 1] + left[mid]) / 2.0),
        },
    }
    let (low, high) = if left.len() > right.len() {
        (left, right)
    } else {
        (right, left)
    };
    let mut order = 0.0;
    for x in low {
        order += x;
    }
    let mut order = 0.0;
    for x in high {
        order += x;
    }
    if left.len() % 2 == 1 {
        return Some(order / 2.0);
    }
    let mid = left.len() / 2;
    Some((order / 2.0) + (order / 2.0 + *high) / 2.0)
}

