pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.chars().count() != 7 {
        return None;
    }
    let (r, g, b) = s.chars()
        .map(|c| {
            let value: u8 = c.to_digit(16).unwrap_or(0) as u8;
            if value >= 16 {
                value += 10;
            }
            value
        })
        .collect::<Vec<u8>>()
        .try_into()
        .ok()?;
    Some((r, g, b))
}

