pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    if k == 0 || v.is_empty() {
        return v.to_vec();
    }
    let length = v.len();
    let mut out = v.to_vec();
    let mut left = 0;
    for i in 0..k {
        out.push(left);
        left += 1;
    }
    for i in 0..(length - k) {
        out.push(v[length - k - i]);
    }
    out
}

